-- Generated by scripts/hourly-coins-sql.mjs. Do not edit by hand.
-- Hourly events pay coins again (20 Oct 2026, the owner): a quarter of the 6-hour events' coins, (50 + 500 / 250 / 125 for the first three in a
-- league, 25 for every other finisher) × the league's coins (Sprout League ×1 up to Village Legends ×20): a Sprout finisher
-- gets 75, the first in the Village Legends 11,000. Diamonds stay 8 / 5 / 3 and 1. The family bonus: +3 diamonds and a flat +500 coins.
-- Run it after the site and farm-api of this change are live, between hh:05 and hh:50 UTC (an event may run). Save the
-- harvest_event_% definitions and the live_events rows that have not started first (no PITR). One transaction: any failed check
-- rolls all of it back. Running it twice changes nothing. The running event and every settled one keep their rewards.
begin;
set local lock_timeout='5s';
do $guard$
declare want jsonb:='{"harvest_event_board(uuid)":["c509587a78de0cdc576cd6681ba9a29f"],"harvest_event_claim(uuid,uuid)":["de2cdc930a667bc9c80f3737fca9929c"],"harvest_event_league(integer)":["ea594ad4aeb110d5858de5cdaf68ddbe"],"harvest_event_league_for(integer,jsonb,smallint)":["72ba9cc06862bab8a5778cecd96fbaa7"],"harvest_event_pause(timestamptz)":["ec48c1c17c8751f6ef231c9ac25b9f3e"],"harvest_event_pick(bigint)":["a4354b4070af10908e1e609720cba26d"],"harvest_event_progress()":["4681019789851e424d9a12f74f843077"],"harvest_event_schedule()":["3d8632d66217916f3a9d18a74d340577","f8478e0aad67d7042618a8ed31dc5f9a"],"harvest_event_settle(uuid)":["1fd63cef297e5f96636fe7da62596b13","6ea64827b008b9f954039e09af376e30"],"harvest_event_validate()":["15a89d91355e859133cecff10277a0fc","d4df362a2159670d745901819c9d4aa6"]}';
 fname text; have text;
begin
 -- Not in the cron job's hand-out (:55) and not when an event starts (:00).
 if extract(minute from now()) not between 5 and 50 then raise exception 'Run this between hh:05 and hh:50 UTC.'; end if;
 for fname in select jsonb_object_keys(want) loop
  select md5(prosrc) into have from pg_proc where oid=to_regprocedure('public.'||fname);
  if have is null or not (want->fname ? have) then raise exception 'public.% is not the one this file expects (md5 %); read the live definition first', fname, have; end if;
 end loop;
end $guard$;
-- The rewards of every event that has started, to check they stayed as they were.
create temp table hourly_coins_started on commit drop as select id,rewards from public.live_events where starts_at<=now();

-- 1. The check accepts an hourly event's coins (first: the events made ahead get them in step 4).
create or replace function public.harvest_event_validate()
 returns trigger language plpgsql set search_path to '' as $function$
declare objective jsonb; k text;
begin
 perform pg_advisory_xact_lock(724919);
 if TG_OP='UPDATE' and old.starts_at<=now() and (new.title<>old.title or new.description<>old.description or new.starts_at<>old.starts_at or new.ends_at<>old.ends_at or new.objectives<>old.objectives or new.rewards<>old.rewards) then raise exception 'Started events are frozen. Create a new event to change the rules.'; end if;
 if new.active and new.ends_at>now() and exists(select 1 from public.live_events e where e.id<>new.id and e.active and e.starts_at<new.ends_at and e.ends_at>new.starts_at) then raise exception 'Active events cannot overlap.'; end if;
 if jsonb_typeof(new.objectives)<>'array' or jsonb_array_length(new.objectives) not between 1 and 4 then raise exception 'Choose 1–4 objectives.'; end if;
 for objective in select value from jsonb_array_elements(new.objectives) loop
  if coalesce(objective->>'stat','') not in ('harvested','produced','watered','tended','chores','deliveries','harvest_wheat','harvest_corn','harvest_lettuce','harvest_barley','harvest_greenbeans','harvest_cabbage','made_eggs','planted','sold','earned','coins_spent','diamonds_spent','activities','upgrades','made_feed','made_milk','made_cheese','made_flour','fertilized','harvest_cauliflower','made_grainmeal','made_bread','parallel_batches','boosts_used','activity_rounds','sold_wheat','made_salad','made_fertilizer','sold_eggs','made_vegetables','made_pickles','made_oil','made_beangratin','made_applepie','made_orchardsalad','made_pie','made_stew','sold_cheese','tractor','glasshouse_batches','made_berrysmoothie','made_applecompote','made_pickledbeans','made_truffleomelette','made_berrycheesecake','made_applejuice','made_orchardjuice','made_berrypreserves','made_truffles','made_honey','made_wool','made_squashsoup','made_yarn','made_cloth','made_goatmilk','made_goatcheese','made_candles','made_cider','made_cherryjam','valley_baskets','made_stone','made_ironore','made_timber','made_packedlunch','village_batches','made_plank','village_requests','lake_fish','made_clay','made_potatoes','made_ironbar','made_pickaxe','made_rooftile','made_flax','made_lavender','made_linen','made_builderscrate','made_lavendersoap','made_scentedsachet','made_silvercandlestick','made_rubyring') or coalesce((objective->>'target')::integer,0) not between 1 and 10000 then raise exception 'Invalid event objective.'; end if;
 end loop;
 if (select count(distinct value->>'stat') from jsonb_array_elements(new.objectives))<>jsonb_array_length(new.objectives) then raise exception 'Objectives must be unique.'; end if;
 foreach k in array array['coins','diamondMin','diamondMax','participantStep','poolCap'] loop
  if not new.rewards ? k or jsonb_typeof(new.rewards->k)<>'number' or (new.rewards->>k)::numeric<>trunc((new.rewards->>k)::numeric) then raise exception 'Reward settings must be whole numbers.'; end if;
 end loop;
 if (new.rewards->>'coins')::integer not between 0 and 300 or (new.rewards->>'diamondMin')::integer not between 0 and 1 or (new.rewards->>'diamondMax')::integer not between 1 and 3 or (new.rewards->>'participantStep')::integer not between 10 and 1000 or (new.rewards->>'poolCap')::integer not between 0 and 200 then raise exception 'Reward settings exceed safe limits.'; end if;
 if new.rewards ? 'podium' then
  if jsonb_typeof(new.rewards->'podium')<>'array' or jsonb_array_length(new.rewards->'podium')<>3
   -- (a case, not an or: SQL does not promise to stop before casting a non-number)
   or exists(select 1 from jsonb_array_elements(new.rewards->'podium') d where case when jsonb_typeof(d)='number' then d::text::numeric<>trunc(d::text::numeric) or d::text::numeric not between 0 and 25 else true end)
   then raise exception 'Podium diamonds must be 3 whole numbers from 0 to 25.'; end if;
  foreach k in array array['finisher','familyFinishers','familyDiamonds'] loop
   if not new.rewards ? k or jsonb_typeof(new.rewards->k)<>'number' or (new.rewards->>k)::numeric<>trunc((new.rewards->>k)::numeric) then raise exception 'Reward settings must be whole numbers.'; end if;
  end loop;
  if (new.rewards->>'finisher')::integer not between 0 and 3 or (new.rewards->>'familyFinishers')::integer not between 2 and 10
   or (new.rewards->>'familyDiamonds')::integer not between 0 and 5
   then raise exception 'Reward settings exceed safe limits.'; end if;
  -- Coins (20 Oct 2026, later): podiumCoins, finisherCoins and familyCoins together, or none of them and coins 0 (the first hourly events).
  if new.rewards ?| array['podiumCoins','finisherCoins','familyCoins'] then
   if not new.rewards ?& array['podiumCoins','finisherCoins','familyCoins'] or jsonb_typeof(new.rewards->'podiumCoins')<>'array' or jsonb_array_length(new.rewards->'podiumCoins')<>3
    or exists(select 1 from jsonb_array_elements(new.rewards->'podiumCoins') d where case when jsonb_typeof(d)='number' then d::text::numeric<>trunc(d::text::numeric) or d::text::numeric not between 0 and 2000 else true end)
    then raise exception 'Podium coins must be 3 whole numbers from 0 to 2000.'; end if;
   foreach k in array array['finisherCoins','familyCoins'] loop
    if jsonb_typeof(new.rewards->k)<>'number' or (new.rewards->>k)::numeric<>trunc((new.rewards->>k)::numeric) then raise exception 'Reward settings must be whole numbers.'; end if;
   end loop;
   if (new.rewards->>'finisherCoins')::integer not between 0 and 200 or (new.rewards->>'familyCoins')::integer not between 0 and 1000 then raise exception 'Reward settings exceed safe limits.'; end if;
  elsif (new.rewards->>'coins')::integer<>0 then raise exception 'Reward settings exceed safe limits.';
  end if;
 end if;
 return new;
end $function$;

-- 2. Settle pays them: (coins + the place's coins) × the league, and the family bonus's flat coins.
create or replace function public.harvest_event_settle(p_event uuid)
 returns void language plpgsql set search_path to '' as $function$
declare e public.live_events; n integer; per_player integer; budget integer; hour boolean; fam_n integer; fam_d integer; fam_c integer;
begin
 select * into e from public.live_events where id=p_event for update;
 if not found or e.ends_at>now() or e.settled_at is not null then return; end if;
 -- The prizes are the event's own (rewards, 20 Oct 2026): an hourly event carries its podium and finisher diamonds and coins; an
 -- older event without podium keeps the rules it was made with (event-podium-2026-10-08.sql, world-two-leagues-b.sql).
 hour:=e.rewards ? 'podium';
 fam_n:=coalesce((e.rewards->>'familyFinishers')::integer,3);fam_d:=coalesce((e.rewards->>'familyDiamonds')::integer,3);fam_c:=case when hour then coalesce((e.rewards->>'familyCoins')::integer,0) else 200 end;
 -- The league of every farmer in the event, by their level now (1 Oct 2026), and then whether they finished their league's goals
 -- (live-event-league-goals.sql; an event without per-league goals uses its own for everyone). Within the leagues the event was made
 -- with, and at most the Valley Legends for a farmer who first counted below level 100 (world 1; 20 Oct 2026).
 update public.live_event_players p set league=public.harvest_event_league_for(s.level,e.leagues,p.world)
  from public.player_stats s where p.event_id=p_event and s.player_id=p.player_id;
 update public.live_event_players set league=0 where event_id=p_event and league is null;
 update public.live_event_players p set qualified=(not exists(select 1 from jsonb_array_elements(coalesce(e.leagues->p.league->'objectives',e.objectives)) o where coalesce((p.progress->>(o->>'stat'))::integer,0)<(o->>'target')::integer)) where event_id=p_event;
 select count(*) into n from public.live_event_players where event_id=p_event and qualified;
 per_player:=least((e.rewards->>'diamondMax')::integer,(e.rewards->>'diamondMin')::integer+floor(sqrt(n::numeric/(e.rewards->>'participantStep')::integer))::integer);
 budget:=least((e.rewards->>'poolCap')::integer,n*per_player);
 -- Completed players are ordered by completion time within their league, UUID as deterministic tie-break. The first three of each
 -- league also win a podium prize on top (+2000, +1000, +500 coins) and every later finisher +100 coins; the event's coins and the
 -- podium coins are × the league's number (1–5), 8 for the Valley Legends, 10–20 for the village leagues. Diamonds are a fixed 25, 15, 10 and 3 in every league
 -- (7 Oct 2026; 50, 30, 20 and 5 before), however many finished in the league (8 Oct 2026; on 7 Oct only with 4 or more).
 -- All of that is for an event from before 20 Oct 2026. An hourly event pays the diamonds of its own rewards (podium, then finisher
 -- from 4th place on), and its coins plus the place's podiumCoins (finisherCoins from 4th place on), × the league (20 Oct 2026, later;
 -- the first hourly events have no coins in their rewards and pay none).
 with ranked as (select player_id,league,row_number() over(partition by league order by last_at,player_id) as rank from public.live_event_players where event_id=p_event and qualified)
 update public.live_event_players p set
  coins=case when hour then (coalesce((e.rewards->>'coins')::integer,0)+coalesce((e.rewards->'podiumCoins'->>(r.rank::integer-1))::integer,(e.rewards->>'finisherCoins')::integer,0))*(array[1,2,3,4,5,8,10,12,14,16,18,20])[r.league+1] else ((e.rewards->>'coins')::integer+(case r.rank when 1 then 2000 when 2 then 1000 when 3 then 500 else 100 end))*(array[1,2,3,4,5,8,10,12,14,16,18,20])[r.league+1] end,
  diamonds=case when hour then coalesce((e.rewards->'podium'->>(r.rank::integer-1))::integer,(e.rewards->>'finisher')::integer)
   else (case r.rank when 1 then 25 when 2 then 15 when 3 then 10 else 3 end) end
  from ranked r where p.event_id=p_event and p.player_id=r.player_id;
 -- The family bonus (27 Sep 2026): fam_n or more finishers from one family in this event each get fam_d diamonds, and fam_c coins:
 -- 200 on an event from before 20 Oct 2026, an hourly event's familyCoins (flat, no league factor) (+5 diamonds until 7 Oct 2026).
 with fam as (select m.family_id,lp.player_id from public.live_event_players lp
   join public.family_members m on m.player_id=lp.player_id and m.left_at is null
   join public.families f on f.id=m.family_id and f.deleted_at is null
   where lp.event_id=p_event and lp.qualified),
  big as (select family_id from fam group by family_id having count(*)>=fam_n)
 update public.live_event_players p set coins=p.coins+fam_c,diamonds=p.diamonds+fam_d
  from fam where fam.family_id in (select family_id from big) and p.event_id=p_event and p.player_id=fam.player_id;
 update public.live_events set settled_at=now(),participants=(select count(*) from public.live_event_players where event_id=p_event),qualified=n,diamond_pool=budget where id=p_event;
 -- Village events (20 Oct 2026): the events finished in a village league count in village_events_finished too. Both are recounts.
 update public.player_stats s set events_finished=(select count(*) from public.live_event_players lp where lp.player_id=s.player_id and lp.qualified),
  village_events_finished=(select count(*) from public.live_event_players lp where lp.player_id=s.player_id and lp.qualified and lp.league>=6)
  where s.player_id in (select player_id from public.live_event_players where event_id=p_event and qualified);
end $function$;

-- 3. Schedule: new events carry the coins.
create or replace function public.harvest_event_schedule()
 returns void language plpgsql set search_path to '' as $function$
declare
 rewards constant jsonb:='{"coins":50,"diamondMin":1,"diamondMax":1,"participantStep":25,"poolCap":50,"podium":[8,5,3],"finisher":1,"familyFinishers":3,"familyDiamonds":3,"podiumCoins":[500,250,125],"finisherCoins":25,"familyCoins":500}';
 slot bigint:=floor(extract(epoch from now())/3600)::bigint;
 paused timestamptz; ended uuid; n bigint; starts timestamptz; event_id uuid; t jsonb;
begin
 for ended in select e.id from public.live_events e where e.ends_at<=now() and e.settled_at is null loop
  perform public.harvest_event_settle(ended);
 end loop;
 select c.paused_until into paused from public.event_config c where c.id;
 -- Automatic events nobody has a row in that have not started: the 6-hour ones from before 20 Oct 2026, and hourly ones inside a pause.
 delete from public.live_events e where e.created_by is null and e.settled_at is null and e.starts_at>now()
  and (e.ends_at-e.starts_at>interval '55 minutes' or e.starts_at<paused)
  and not exists(select 1 from public.live_event_players lp where lp.event_id=e.id);
 for n in slot..slot+2 loop
  starts:=to_timestamp(n*3600);
  -- Never an event with under 50 minutes to play (after a pause or a late run), never inside a pause.
  continue when starts<now()-interval '5 minutes' or starts<paused;
  event_id:=md5('harvest-hour-event:'||n)::uuid;
  continue when exists(select 1 from public.live_events e where e.id=event_id);
  t:=public.harvest_event_pick(n);
  begin
   insert into public.live_events(id,title,description,starts_at,ends_at,active,objectives,rewards,created_by,leagues)
   values(event_id,t->>'title',t->>'description',starts,starts+interval '55 minutes',true,t->'objectives',rewards,null,t->'leagues');
  exception
   -- An operator's own active event already holds this time, or a parallel run just created the same slot.
   when raise_exception or unique_violation then null;
  end;
 end loop;
end $function$;

-- 4. The hourly events made ahead that have not started get the coins; their diamonds stay. Not the running one, nor a settled one.
update public.live_events set rewards=rewards||'{"coins":50,"podiumCoins":[500,250,125],"finisherCoins":25,"familyCoins":500}'::jsonb
 where starts_at>now() and settled_at is null and rewards ? 'podium' and not rewards ? 'podiumCoins';

-- 5. After-check, in the same transaction.
do $after$ declare fname text; want jsonb:='{"harvest_event_validate()":"d4df362a2159670d745901819c9d4aa6","harvest_event_settle(uuid)":"6ea64827b008b9f954039e09af376e30","harvest_event_schedule()":"f8478e0aad67d7042618a8ed31dc5f9a"}'; kept jsonb:='{"harvest_event_board(uuid)":"c509587a78de0cdc576cd6681ba9a29f","harvest_event_claim(uuid,uuid)":"de2cdc930a667bc9c80f3737fca9929c","harvest_event_league(integer)":"ea594ad4aeb110d5858de5cdaf68ddbe","harvest_event_league_for(integer,jsonb,smallint)":"72ba9cc06862bab8a5778cecd96fbaa7","harvest_event_pause(timestamptz)":"ec48c1c17c8751f6ef231c9ac25b9f3e","harvest_event_pick(bigint)":"a4354b4070af10908e1e609720cba26d","harvest_event_progress()":"4681019789851e424d9a12f74f843077"}'; begin
 for fname in select jsonb_object_keys(want) loop
  -- is distinct from: a missing function (NULL) fails too.
  if (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.'||fname)) is distinct from want->>fname then raise exception 'public.% did not come out as generated',fname; end if;
 end loop;
 for fname in select jsonb_object_keys(kept) loop
  if (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.'||fname)) is distinct from kept->>fname then raise exception 'public.% changed',fname; end if;
 end loop;
 -- The headers and grants of the three as live: not security definer, volatile, search_path '', only postgres and service_role.
 if exists(select 1 from unnest(array['harvest_event_settle(uuid)','harvest_event_schedule()','harvest_event_validate()']) as replaced(sig)
    left join pg_proc p on p.oid=to_regprocedure('public.'||replaced.sig)
    where p.oid is null or p.prosecdef or p.provolatile<>'v' or p.proconfig is distinct from array['search_path=""']
     or p.proacl::text is distinct from '{postgres=X/postgres,service_role=X/postgres}')
  then raise exception 'a function header or grant changed'; end if;
 -- Every hourly event that has not started has the coins; the automatic ones exactly the new rewards.
 if exists(select 1 from public.live_events e where e.starts_at>now() and e.settled_at is null and e.rewards ? 'podium'
    and (not e.rewards @> '{"coins":50,"podiumCoins":[500,250,125],"finisherCoins":25,"familyCoins":500}'::jsonb or (e.created_by is null and e.rewards<>'{"coins":50,"diamondMin":1,"diamondMax":1,"participantStep":25,"poolCap":50,"podium":[8,5,3],"finisher":1,"familyFinishers":3,"familyDiamonds":3,"podiumCoins":[500,250,125],"finisherCoins":25,"familyCoins":500}'::jsonb)))
  then raise exception 'an hourly event made ahead has no coins'; end if;
 -- The events that had started keep their rewards.
 if exists(select 1 from hourly_coins_started s left join public.live_events e on e.id=s.id where e.rewards is distinct from s.rewards)
  then raise exception 'the rewards of an event that had started changed'; end if;
 -- The check accepts every event settle and the schedule still have to write (the running one without coins, the ones ahead with).
 begin
  update public.live_events set rewards=rewards where settled_at is null;
  raise exception using errcode='HC001';
 exception when sqlstate 'HC001' then null;
 end;
end $after$;
commit;
